import{c as l,Q as a,j as o,m as s}from"./chunks/framework.rWdQudnF.js";const h=JSON.parse('{"title":"操作系统概述","description":"","frontmatter":{"title":"操作系统概述"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/操作系统概述.md","filePath":"综合知识/系统基础/操作系统/操作系统概述.md","lastUpdated":null}'),i={name:"综合知识/系统基础/操作系统/操作系统概述.md"};function d(r,t,n,e,u,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 操作系统定义与作用 ✅ 2026-05-16</li><li>[x] 四大特征与五大功能 ✅ 2026-05-15</li><li>[x] 操作系统分类 ✅ 2026-05-15</li><li>[x] 嵌入式操作系统 ✅ 2026-05-15</li><li>[x] 网络操作系统 ✅ 2026-05-15</li><li>[x] 内核特征 ✅ 2026-05-15</li><li>[x] 软件分类（系统软件 vs 应用软件） ✅ 2026-05-15</li><li>[x] 系统监视 ✅ 2026-05-15</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="定义与作用" tabindex="-1">定义与作用 <a class="header-anchor" href="#定义与作用" aria-label="Permalink to &quot;定义与作用&quot;">​</a></h3><p><strong>定义</strong>：能有效地组织和管理系统中的各种软/硬件资源，合理地组织计算机系统工作流程，控制程序的执行，并向用户提供良好的工作环境和友好的接口。</p><p><strong>三个作用</strong>：</p><ul><li>管理计算机中运行的程序和分配各种软硬件资源</li><li>为用户提供友善的人机界面</li><li>为应用程序的开发和运行提供高效率的平台</li></ul><h3 id="四大特征与五大功能" tabindex="-1">四大特征与五大功能 <a class="header-anchor" href="#四大特征与五大功能" aria-label="Permalink to &quot;四大特征与五大功能&quot;">​</a></h3><p><strong>四个特征</strong>：并发性、共享性、虚拟性、不确定性</p><ul><li>并发 vs 并行：并发是宏观的（分时调度），并行是微观的</li></ul><p><strong>五大功能</strong>：</p><ul><li>进程管理 — 对 CPU 执行&quot;时间&quot;进行管理</li><li>文件管理 — 文件存储空间管理、目录管理、读写管理和存取控制</li><li>存储管理 — 对主存储器&quot;空间&quot;进行管理</li><li>设备管理 — 对硬件设备的管理，包括输入/输出设备的分配、启动、完成和回收</li><li>作业管理 — 任务、界面管理、人机交互等</li></ul><h3 id="操作系统分类" tabindex="-1">操作系统分类 <a class="header-anchor" href="#操作系统分类" aria-label="Permalink to &quot;操作系统分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特点</th></tr></thead><tbody><tr><td>批处理操作系统</td><td>单道/多道批处理（主机与外设可并行）</td></tr><tr><td>分时操作系统</td><td>CPU 时间划分为时间片，轮流为各终端服务</td></tr><tr><td>实时操作系统</td><td>在被控对象允许的时间范围内快速反应，可靠性要求高</td></tr><tr><td>网络操作系统</td><td>集中模式 / C/S 模式 / 对等模式</td></tr><tr><td>分布式操作系统</td><td>多台计算机无主次之分，通过通信交换信息</td></tr><tr><td>微机操作系统</td><td>Windows、Mac OS、Linux</td></tr></tbody></table><blockquote><p>⚠️ 多道批处理：允许多个作业同时装入内存，宏观并行微观串行。同一时刻可有多个作业在内存。</p></blockquote><h3 id="嵌入式操作系统" tabindex="-1">嵌入式操作系统 <a class="header-anchor" href="#嵌入式操作系统" aria-label="Permalink to &quot;嵌入式操作系统&quot;">​</a></h3><blockquote><p>🎯 一句话结论：嵌入式 OS 的特点是<strong>微型化、可定制、实时性、可靠性、易移植性</strong>。⚠️ 图形界面友好性<strong>不是</strong>主要特点。</p></blockquote><ul><li>易移植性：采用 HAL（硬件抽象层）和 BSP（板级支持包）设计</li><li>初始化过程（自底向上）：片级初始化 → 板级初始化 → 系统初始化</li></ul><h3 id="网络操作系统" tabindex="-1">网络操作系统 <a class="header-anchor" href="#网络操作系统" aria-label="Permalink to &quot;网络操作系统&quot;">​</a></h3><blockquote><p>🎯 一句话结论：硬件独立性指<strong>可运行在不同网络硬件上并能与其他网络连接</strong>，不依赖特定硬件平台。</p></blockquote><h3 id="内核特征" tabindex="-1">内核特征 <a class="header-anchor" href="#内核特征" aria-label="Permalink to &quot;内核特征&quot;">​</a></h3><blockquote><p>🎯 一句话结论：内核以 CPU 最高优先级运行、可执行特权指令、可直接访问全部主存空间。⚠️ 内核<strong>必须常驻内存</strong>。</p></blockquote><h3 id="软件分类" tabindex="-1">软件分类 <a class="header-anchor" href="#软件分类" aria-label="Permalink to &quot;软件分类&quot;">​</a></h3><blockquote><p>🎯 一句话结论：系统软件不依赖特定应用领域，应用软件为特定领域设计。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td>系统软件</td><td>控制和管理计算机资源，为应用软件提供运行服务，<strong>不依赖特定应用领域</strong></td><td>操作系统、编译程序、设备驱动</td></tr><tr><td>应用软件</td><td>为<strong>特定应用领域</strong>设计的软件</td><td>财务软件</td></tr></tbody></table><p>软件系统的完整构成 = <strong>程序 + 相关文档资料 + 数据的集合</strong>（不只是程序）。</p><h3 id="系统监视" tabindex="-1">系统监视 <a class="header-anchor" href="#系统监视" aria-label="Permalink to &quot;系统监视&quot;">​</a></h3><blockquote><p>🎯 一句话结论：系统监视三种方式 — ① 系统命令 ② 系统记录文件 ③ 监控工具（如 Windows Perfmon）。</p></blockquote><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>系统命令</td><td>直接执行系统命令查看状态</td><td>Linux <code>ps</code>、<code>last</code></td></tr><tr><td>系统记录文件</td><td>查阅系统日志</td><td><code>/var/log/</code></td></tr><tr><td>监控工具</td><td>集成命令、文件记录和可视化的监控工具</td><td>Windows <strong>Perfmon</strong></td></tr></tbody></table><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q39] 系统监视</strong></p><p>进行系统监视通常有三种方式：一是通过（ ），如UNIX／Linux系统中的ps、last等；二是通过系统记录文件查阅系统在特定时间内的运行状态；三是集成命令、文件记录和可视化技术的监控工具，如（ ）。</p><ul><li>A. 系统命令</li><li>B. 系统调用</li><li>C. 系统接口</li><li>D. 系统功能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：ps、last 是系统命令，第一空填&quot;系统命令&quot;。</p></div></details><hr><p><strong>[Q40] 系统监视</strong></p><p>第二问</p><p>进行系统监视通常有三种方式：一是通过（ ），如UNIX／Linux系统中的ps、last等；二是通过系统记录文件查阅系统在特定时间内的运行状态；三是集成命令、文件记录和可视化技术的监控工具，如（ ）。</p><ul><li>A. Windows的netstat</li><li>B. Linux的 iptables</li><li>C. Windows的 Perfmon</li><li>D. Linux的top</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：题目第三空考的是&quot;集成命令、文件记录和<strong>可视化技术</strong>&quot;的监控工具，关键词在&quot;可视化&quot;——只有 C 是图形化工具。</p><table tabindex="0"><thead><tr><th>选项</th><th>是什么</th><th>为什么不对/对</th></tr></thead><tbody><tr><td><strong>A. netstat</strong></td><td>Windows 命令行网络统计工具</td><td>❌ 命令行，无图形化</td></tr><tr><td><strong>B. iptables</strong></td><td>Linux 防火墙规则配置工具</td><td>❌ 防火墙，不是监视工具</td></tr><tr><td><strong>C. Perfmon</strong> ✅</td><td>Windows 图形化性能监视器，有图表、曲线、日志</td><td>✅ <strong>集成命令行+记录+可视化</strong></td></tr><tr><td><strong>D. top</strong></td><td>Linux 命令行实时进程查看</td><td>❌ 虽然有界面但依然是命令行交互，不算图形化&quot;可视化技术&quot;</td></tr></tbody></table></div></details><hr><p><strong>[Q95] 多道批处理</strong></p><p>关于多道批处理操作系统的特点，下列说法错误的是（ ）。</p><ul><li>A. 允许多个作业同时装入内存</li><li>B. 宏观上并行运行</li><li>C. 微观上串行运行</li><li>D. 同一时刻只能有一个作业装入内存</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：多道批处理允许<strong>多个作业同时装入内存</strong>，宏观并行、微观串行。D 说反了。</p></div></details><hr><p><strong>[Q96] 操作系统作用</strong></p><p>下列不属于操作系统主要作用的是（ ）。</p><ul><li>A. 管理和分配系统资源</li><li>B. 提供友善的人机界面</li><li>C. 为应用程序提供运行平台</li><li>D. 直接处理业务数据计算</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：OS 不直接处理业务数据，那是应用软件的事。</p></div></details><hr><p><strong>[Q98] 内核特征</strong></p><p>关于操作系统内核的特征，下列说法错误的是（ ）。</p><ul><li>A. 内核以CPU的最高优先级运行</li><li>B. 内核可以执行特权指令</li><li>C. 内核不需要常驻内存</li><li>D. 内核可以直接访问全部主存空间</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：内核是操作系统的核心，<strong>必须常驻内存</strong>，关机才能卸下。选项辨析：</p><table tabindex="0"><thead><tr><th>选项</th><th>判断</th><th>原因</th></tr></thead><tbody><tr><td><strong>A.</strong> 内核以CPU最高优先级运行</td><td>✅ 正确</td><td>内核运行在<strong>核心态（管态）</strong>，优先级高于所有用户进程</td></tr><tr><td><strong>B.</strong> 内核可以执行特权指令</td><td>✅ 正确</td><td>核心态下可执行所有指令，包括启动I/O、修改页表等<strong>特权指令</strong>；用户态则禁止</td></tr><tr><td><strong>C.</strong> 内核不需要常驻内存</td><td>❌ <strong>错误</strong></td><td>内核负责进程调度、内存管理、中断处理等基础功能，一旦缺页自身都无法运行，因此<strong>必须常驻</strong></td></tr><tr><td><strong>D.</strong> 内核可以直接访问全部主存空间</td><td>✅ 正确</td><td>核心态下<strong>地址空间不受限制</strong>，内核可以访问和管理所有物理内存（包括用户进程的内存区域），用于进程切换、内存分配等操作</td></tr></tbody></table></div></details><hr><p><strong>[Q99] 应用软件</strong></p><p>下列软件中，属于应用软件的是（ ）。</p><ul><li>A. 操作系统</li><li>B. 设备驱动程序</li><li>C. 财务软件</li><li>D. 编译程序</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：财务软件为特定领域设计→应用软件；其余三项都是系统软件。</p></div></details><hr><p><strong>[Q100] 系统软件</strong></p><p>关于系统软件的特点，下列说法错误的是（ ）。</p><ul><li>A. 是为特定应用领域设计的软件</li><li>B. 对计算机系统的资源进行控制和管理</li><li>C. 为其他应用软件的运行提供服务</li><li>D. 不依赖特定应用领域</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：系统软件<strong>不依赖特定应用领域</strong>；A 描述的是应用软件。</p></div></details><hr><p><strong>[Q101] 软件构成</strong></p><p>软件系统的完整构成包括（ ）。</p><ul><li>A. 仅包括程序和数据</li><li>B. 仅包括程序和文档资料</li><li>C. 程序、相关文档资料和数据的集合</li><li>D. 仅包括可执行程序</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：软件 = 程序 + 文档 + 数据，三者缺一不可。</p></div></details>',70)])])}const g=l(i,[["render",d]]);export{h as __pageData,g as default};
